"""Real curve pixels, public score timing, music lifecycle and mobile controls."""
import os,json
from pathlib import Path
from playwright.sync_api import sync_playwright
base=os.environ.get('UNITY_URL','http://127.0.0.1:3483');out=Path(os.environ.get('BACCARAT_CURL_QA','/tmp/baccarat-curl-qa'));out.mkdir(exist_ok=True,parents=True)
with sync_playwright() as p:
 args=['--no-sandbox'];
 if os.environ.get('PROXY_SPKI'):args+=['--ignore-certificate-errors-spki-list='+os.environ['PROXY_SPKI']]
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=args);page=b.new_page(viewport={'width':390,'height':844},has_touch=True);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(base+'/baccarat/index.html');page.locator('[data-action=tables]').click();page.locator('[data-action="start:lounge"]').click();page.locator('[data-action="bet:player"]').click();page.locator('[data-action=confirm]').click();page.locator('#squeeze-dialog[open]').wait_for(timeout=15000);page.locator('.has-curl').wait_for();page.wait_for_function('()=>document.querySelector("#baccarat-music").readyState>=3');music=page.locator('#baccarat-music').evaluate('a=>({time:a.currentTime,duration:a.duration,paused:a.paused,loop:a.loop,error:a.error?.message})');assert not music['paused'] and music['loop'] and music['time']>0 and music['duration']>45 and not music['error'];assert page.locator('audio').count()==1
 seen=page.evaluate('BACCARAT.session.state.round.revealed');points=page.locator('.points').all_text_contents()
 for value in [0,20,40,55,75,95]:
  page.locator('#squeeze-range').fill(str(value));assert page.evaluate('BACCARAT.session.state.round.revealed')==seen;assert page.locator('.points').all_text_contents()==points;page.screenshot(path=str(out/f'curl-{value}.png'))
 page.locator('[data-show=hold]').click();page.locator('#settings-link').click();pos=page.locator('#baccarat-music').evaluate('a=>a.currentTime');page.locator('[data-setting=bgm]').fill('0');assert page.locator('#baccarat-music').evaluate('a=>a.paused');page.wait_for_timeout(200);assert abs(page.locator('#baccarat-music').evaluate('a=>a.currentTime')-pos)<.1;page.locator('[data-setting=bgm]').fill('0.3');page.wait_for_timeout(200);assert not page.locator('#baccarat-music').evaluate('a=>a.paused');assert page.locator('#baccarat-music').evaluate('a=>a.currentTime')>=pos
 page.locator('[data-action=back]').click();page.locator('[data-action=resume-deal]').click();page.locator('#squeeze-dialog[open]').wait_for();assert page.locator('#squeeze-range').input_value()=='95'
 for width in [375,390,414]:
  page.set_viewport_size({'width':width,'height':844});page.screenshot(path=str(out/f'curve-mobile-{width}.png'));assert not page.evaluate('()=>document.documentElement.scrollWidth>innerWidth');assert page.locator('[data-show=full]').bounding_box()['height']>=44
 page.locator('#squeeze-range').fill('100');variance=page.locator('.curl-canvas').evaluate('c=>{const gl=c.getContext("webgl");const n=Math.round(c.height*.055),d=new Uint8Array(n*4);gl.readPixels(Math.round(c.width/2),Math.round(c.height*.76),1,n,gl.RGBA,gl.UNSIGNED_BYTE,d);const r=[];for(let i=0;i<d.length;i+=4)r.push(d[i]);return {variation:Math.max(...r)-Math.min(...r),min:Math.min(...r)}}');assert variance['variation']<18 and variance['min']>150,('visible texture seams',variance)
 page.wait_for_function("()=>BACCARAT.session.state.phase==='result'");assert page.evaluate('BACCARAT.session.state.stats.rounds')==1;assert not errors,errors
 (out/'curl-browser.json').write_text(json.dumps({'music':music,'mutePauseResume':True,'oneMusicElement':True,'realCurveSurface':True,'blankPaperPixels':variance,'noEarlyPoints':True,'holdProgress':95,'widths':[375,390,414],'errors':errors},indent=2));b.close();print('curl and music lifecycle passed',flush=True)
